SELECT ROWNUM ,A.BUYER ,B.COM_NAME_LOC ,A.BULK_NO ,A.BUYER_ITEM_NO ,A.STATUS ,A.BULK_TYPE ,A.EVLT_METHOD ,A.SG_NO ,A.DESCRIPTION ,A.SPECIFICATION ,A.MAKER_NAME ,A.UNIT_MEASURE ,A.ORIGIN_CODE ,A.EXT_AGENT_NAME ,A.PROCESS_TYPE ,A.BULK_QTY ,A.EXT_BULK_UNIT_PRICE ,A.EXT_BULK_AMT ,A.EXT_DSTBT_LV ,A.DLVR_ZONE ,A.KEP_USER_ID ,A.REMARK ,A.REQ_CNT ,A.RECV_CNT ,A.BULK_UNIT_PRICE ,A.BULK_AMT ,A.RDCT_AMT ,A.RDCT_RATE ,A.SELECT_AGENT_NAME ,A.REPLACEMENT_YN ,A.AGENT_REMARK ,TO_CHAR(A.ADD_DATE,'YYYY-MM-DD') AS ADD_DATE ,A.ADD_ID ,TO_CHAR(A.CHANGE_DATE,'YYYY-MM-DD') AS CHANGE_DATE ,A.CHANGE_ID ,(SELECT COD.TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M034' AND COD.CODE = A.PROCESS_TYPE) PROCESS_NM ,(SELECT COD.TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M001' AND COD.CODE = A.ORIGIN_CODE) ORIGIN_NAME ,(SELECT SMG.SG_NAME FROM KEPSGMG SMG WHERE SMG.SG_ID = A.SG_NO) SG_NAME ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =A.KEP_USER_ID) KEP_USR_NAME ,(SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID =A.KEP_USER_ID) KEP_PHONE_NUMBER ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =A.ADD_ID) ADD_NAME ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID =A.CHANGE_ID) CHANGE_NAME FROM KEPBRQDT A, ICOMCMPY B WHERE A.BUYER = B.COM_CODE AND A.STATUS != 'D'
AND A.BUYER IN
#{item}
AND TO_CHAR(A.ADD_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND UPPER(A.BULK_TYPE) LIKE UPPER('%'||#{st_bulk_tpye}||'%')
AND A.KEP_USER_ID = #{st_kep_user_id}
AND A.ADD_ID = #{st_kep_reg_user_id}
ORDER BY A.BUYER, A.ADD_DATE

